_goods_dec_regex = re.compile(r"\[AddTextIf\(EqualTo_string\('(?P<ua_name>[^']+)', GOODS.GetNameWithNoTooltip\), '(?P<en_name>[^']+)'\)]")


def parse_goods_pairs():
    goods_decs = _goods_dec.split("][")
    goods_pairs =[
        match.groupdict()
        for match in _goods_dec_regex.finditer(_goods_dec)
    ]
    goods_cases = {}
    for g in goods_pairs:
        for case in GRAMMATICAL_CASES:
            if not case in goods_cases:
                goods_cases[case] = {}
            goods_cases[case][g["en_name"]] = g["ua_name"]

    sorted_goods_cases = {
        case: dict(sorted(goods_by_name.items()))
        for case, goods_by_name in goods_cases.items()
    }

    print(json.dumps(sorted_goods_cases, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    parse_goods_pairs()
